insert into public.concepts (id, skill_area_id, title, official_summary, reviewed, sort_order) values
  ('iaas', 'cloud_concepts', 'Infrastructure as a Service (IaaS)', 'Rent virtualized computing, storage and networking. You manage the operating system and software.', false, 1),
  ('paas', 'cloud_concepts', 'Platform as a Service (PaaS)', 'A managed platform for building and running apps. The provider manages the operating system and infrastructure.', false, 2),
  ('saas', 'cloud_concepts', 'Software as a Service (SaaS)', 'Finished software delivered over the internet. The provider manages the whole application.', false, 3),
  ('shared-responsibility', 'cloud_concepts', 'Shared responsibility model', 'Security duties are split between the provider and the customer, and the split depends on the service type.', false, 4),
  ('regions', 'architecture_services', 'Azure regions', 'A set of datacenters in a latency defined perimeter connected by a dedicated low latency network.', false, 5),
  ('availability-zones', 'architecture_services', 'Availability zones', 'Physically separate datacenter locations inside a region with independent power, cooling and networking.', false, 6),
  ('azure-policy', 'management_governance', 'Azure Policy', 'Creates and assigns rules that resources must follow, to enforce standards and assess compliance.', false, 7),
  ('rbac', 'management_governance', 'Role-based access control (RBAC)', 'Controls who can do what on which Azure resources by assigning roles at a scope.', false, 8)
on conflict (id) do nothing;

insert into public.concept_explanations (concept_id, world_id, lang, analogy, plain, exam, reviewed) values
  ('iaas', 'matatu', 'en',
   'You rent an empty matatu from a sacco. The owner gives you the vehicle, and you choose the route, set the fare and hire the crew.',
   'You rent the basic computing parts and you manage the system and apps yourself.',
   'IaaS provides virtualized compute, storage and networking. The customer manages the operating system, middleware and applications.', false),
  ('iaas', 'matatu', 'sw',
   'Unakodi matatu tupu kutoka kwa sacco. Mmiliki anatoa gari, wewe unachagua njia, unaweka nauli na unaajiri wafanyakazi.',
   'Unakodi vipande vya msingi vya kompyuta, na unasimamia mfumo na programu mwenyewe.',
   'IaaS hutoa kompyuta pepe, hifadhi na mtandao. Mteja husimamia mfumo endeshi na programu.', false),
  ('paas', 'matatu', 'en',
   'You join a sacco route. The sacco handles the vehicle, repairs and permits, and you just bring your driving and your passengers.',
   'The provider manages the platform, and you only build and run your app.',
   'PaaS provides a managed platform for building and deploying apps. The provider manages the operating system and infrastructure, and the customer manages the app and its data.', false),
  ('paas', 'matatu', 'sw',
   'Unajiunga na njia ya sacco. Sacco inashughulikia gari, matengenezo na vibali, wewe unaleta uendeshaji wako na abiria.',
   'Mtoa huduma anasimamia jukwaa, wewe unajenga na kuendesha programu yako tu.',
   'PaaS hutoa jukwaa linalosimamiwa la kujenga na kuweka programu. Mtoa huduma husimamia mfumo endeshi na miundombinu, mteja husimamia programu na data.', false),
  ('saas', 'matatu', 'en',
   'You board a matatu. You pay the fare and ride, with no worry about the vehicle, the route or the driver.',
   'Ready made software that you just use.',
   'SaaS: the provider manages the entire application stack. The customer uses the software and manages their own data, users and access.', false),
  ('saas', 'matatu', 'sw',
   'Unapanda matatu. Unalipa nauli na kusafiri, huna wasiwasi kuhusu gari, njia wala dereva.',
   'Programu iliyo tayari ambayo unaitumia tu.',
   'SaaS: mtoa huduma husimamia programu yote. Mteja huitumia na kusimamia data, watumiaji na ruhusa zake.', false),
  ('shared-responsibility', 'matatu', 'en',
   'On a matatu trip the owner keeps the vehicle roadworthy and insured, while you look after your own bag and your fare. Some duties, like staying safe in your seat, are shared.',
   'The cloud provider secures the cloud itself, and you secure what you put in it.',
   'The provider is always responsible for the physical datacenter, physical network and physical hosts. The customer is always responsible for data, accounts and identities, and devices. Other duties vary by service type.', false),
  ('shared-responsibility', 'matatu', 'sw',
   'Safarini kwa matatu, mmiliki huhakikisha gari ni salama na lina bima, wewe unalinda mfuko wako na nauli yako. Majukumu mengine, kama kukaa salama kwenye kiti, hugawanywa.',
   'Mtoa huduma analinda wingu lenyewe, wewe unalinda unachoweka ndani yake.',
   'Mtoa huduma daima huwajibika kwa kituo cha data halisi, mtandao halisi na seva halisi. Mteja daima huwajibika kwa data, akaunti na utambulisho, na vifaa. Majukumu mengine hutofautiana kulingana na aina ya huduma.', false),
  ('regions', 'matatu', 'en',
   'Every big town has a cluster of matatu stages close together and joined by fast roads. An Azure region is like that whole cluster of stages.',
   'A region is a group of datacenters in one area, connected by a fast network.',
   'An Azure region is a set of datacenters deployed within a latency defined perimeter and connected through a dedicated regional low latency network.', false),
  ('regions', 'matatu', 'sw',
   'Kila mji mkubwa una vituo vya matatu vilivyo karibu na kuunganishwa kwa barabara za haraka. Eneo la Azure ni kama kundi hilo lote la vituo.',
   'Eneo ni kundi la vituo vya data katika sehemu moja, vilivyounganishwa kwa mtandao wa haraka.',
   'Eneo la Azure ni seti ya vituo vya data ndani ya mpaka wa ucheleweshaji uliobainishwa, vilivyounganishwa kwa mtandao maalum wa ucheleweshaji mdogo.', false),
  ('availability-zones', 'matatu', 'en',
   'One big bus park has three separate stages, each with its own gate, its own generator and its own fuel. If one stage is shut, passengers use another.',
   'Zones are separate datacenters inside one region, so one failure does not stop everything.',
   'Availability zones are physically separate locations within a region, each with independent power, cooling and networking, protecting against datacenter level failure.', false),
  ('availability-zones', 'matatu', 'sw',
   'Stendi moja kubwa ina vituo vitatu tofauti, kila kimoja na lango lake, jenereta yake na mafuta yake. Kituo kimoja kikifungwa, abiria hutumia kingine.',
   'Kanda ni vituo vya data tofauti ndani ya eneo moja, kwa hivyo hitilafu moja haisimamishi kila kitu.',
   'Kanda za upatikanaji ni maeneo halisi tofauti ndani ya eneo, kila moja na umeme, upoaji na mtandao vinavyojitegemea.', false),
  ('azure-policy', 'matatu', 'en',
   'The county sets rules for matatus: no overloading, show your licence, use approved routes only. Inspectors check every matatu and flag the ones breaking the rules.',
   'Policy sets rules for your resources and checks that they follow them.',
   'Azure Policy creates, assigns and manages policies that enforce rules and effects on resources, so they stay compliant with organisation standards.', false),
  ('azure-policy', 'matatu', 'sw',
   'Kaunti huweka sheria kwa matatu: usizidishe abiria, onyesha leseni, tumia njia zilizoidhinishwa tu. Wakaguzi huangalia kila matatu na kuyataja yanayovunja sheria.',
   'Sera huweka sheria kwa rasilimali zako na kukagua kama zinazifuata.',
   'Azure Policy huunda, kugawa na kusimamia sera zinazotekeleza sheria kwenye rasilimali ili zitii viwango vya shirika.', false),
  ('rbac', 'matatu', 'en',
   'The sacco hands out different keys. The driver has the ignition key, the conductor has the cash box, the cleaner has the door key, and nobody gets every key.',
   'RBAC decides who can do what on which resources.',
   'Azure RBAC manages access to Azure resources by assigning roles to a user, group or service principal at a scope, following least privilege.', false),
  ('rbac', 'matatu', 'sw',
   'Sacco hutoa funguo tofauti. Dereva ana ufunguo wa gari, kondakta ana sanduku la pesa, msafishaji ana ufunguo wa mlango, na hakuna anayepewa funguo zote.',
   'RBAC huamua nani anaweza kufanya nini kwenye rasilimali gani.',
   'Azure RBAC husimamia ufikiaji wa rasilimali za Azure kwa kugawa majukumu kwa mtumiaji, kikundi au huduma katika wigo fulani, kwa kanuni ya ruhusa ndogo kabisa.', false)
on conflict (concept_id, world_id, lang) do nothing;

insert into public.questions (id, concept_id, stem, options, difficulty, reviewed) values
  ('00000000-0000-0000-0000-000000000001', 'iaas',
   'A team wants full control of the operating system on a server but does not want to buy physical hardware. Which cloud service type fits best?',
   '[{"id":"a","text":"IaaS","correct":true,"explanation":"You rent virtualized hardware and manage the operating system and software yourself."},{"id":"b","text":"PaaS","correct":false,"explanation":"PaaS manages the operating system for you, so you would not have full control of it."},{"id":"c","text":"SaaS","correct":false,"explanation":"SaaS is finished software. You do not control the server or its operating system."},{"id":"d","text":"On-premises hardware","correct":false,"explanation":"That means buying physical hardware, which the team wants to avoid."}]'::jsonb,
   1, false),
  ('00000000-0000-0000-0000-000000000002', 'paas',
   'A developer wants to publish a web app without patching or managing the underlying operating system. Which model fits best?',
   '[{"id":"a","text":"PaaS","correct":true,"explanation":"The provider manages the operating system and platform, and you manage the app and data."},{"id":"b","text":"IaaS","correct":false,"explanation":"With IaaS you must patch and manage the operating system yourself."},{"id":"c","text":"SaaS","correct":false,"explanation":"SaaS is ready made software. You would not be building and publishing your own app."},{"id":"d","text":"A private on-premises server","correct":false,"explanation":"You would patch and manage everything yourself."}]'::jsonb,
   1, false),
  ('00000000-0000-0000-0000-000000000003', 'saas',
   'A school uses a ready made online email and calendar service. Staff only manage their own accounts and content. Which model is this?',
   '[{"id":"a","text":"SaaS","correct":true,"explanation":"The provider runs the whole application and customers just use it."},{"id":"b","text":"IaaS","correct":false,"explanation":"IaaS gives you raw infrastructure, not a finished email service."},{"id":"c","text":"PaaS","correct":false,"explanation":"PaaS is a platform for building your own apps, not a finished app."},{"id":"d","text":"Hybrid cloud","correct":false,"explanation":"Hybrid combines on-premises and cloud. It is a deployment style, not a service type."}]'::jsonb,
   1, false),
  ('00000000-0000-0000-0000-000000000004', 'shared-responsibility',
   'Which item is always the responsibility of the customer, whatever the cloud service type?',
   '[{"id":"a","text":"The data stored in the cloud","correct":true,"explanation":"Information and data always stay the responsibility of the customer."},{"id":"b","text":"Physical datacenter security","correct":false,"explanation":"The cloud provider always handles the physical datacenter."},{"id":"c","text":"Physical network cabling","correct":false,"explanation":"The physical network is always the provider responsibility."},{"id":"d","text":"Physical host servers","correct":false,"explanation":"The physical hosts are always the provider responsibility."}]'::jsonb,
   2, false),
  ('00000000-0000-0000-0000-000000000005', 'regions',
   'What is an Azure region?',
   '[{"id":"a","text":"A set of datacenters in one area, connected by a dedicated low latency network","correct":true,"explanation":"That is the definition of a region."},{"id":"b","text":"A single datacenter building with one power supply","correct":false,"explanation":"A region contains datacenters, it is not one building."},{"id":"c","text":"A billing account used to pay for services","correct":false,"explanation":"Billing accounts are about payment, not location."},{"id":"d","text":"A group of users with the same permissions","correct":false,"explanation":"That describes a role assignment idea, not a region."}]'::jsonb,
   1, false),
  ('00000000-0000-0000-0000-000000000006', 'availability-zones',
   'An app must keep running if one datacenter in a region fails. What is the best design choice?',
   '[{"id":"a","text":"Spread the app across availability zones","correct":true,"explanation":"Zones are separate datacenters with independent power, cooling and networking."},{"id":"b","text":"Place every virtual machine in the same zone","correct":false,"explanation":"One zone failing would take everything down."},{"id":"c","text":"Choose a larger virtual machine size","correct":false,"explanation":"A bigger machine does not protect against a datacenter failure."},{"id":"d","text":"Add a second subscription","correct":false,"explanation":"Subscriptions are for billing and organisation, not resilience."}]'::jsonb,
   2, false),
  ('00000000-0000-0000-0000-000000000007', 'azure-policy',
   'A company wants to make sure resources can only be created in two approved regions. Which Azure feature enforces this rule?',
   '[{"id":"a","text":"Azure Policy","correct":true,"explanation":"Policy enforces rules on resource properties such as allowed locations."},{"id":"b","text":"Azure RBAC","correct":false,"explanation":"RBAC controls who can act, not which regions resources may use."},{"id":"c","text":"A resource lock","correct":false,"explanation":"Locks prevent deleting or changing resources, they do not restrict locations."},{"id":"d","text":"Availability zones","correct":false,"explanation":"Zones improve resilience, they do not enforce rules."}]'::jsonb,
   2, false),
  ('00000000-0000-0000-0000-000000000008', 'rbac',
   'A junior admin must be able to restart virtual machines in one resource group but do nothing else in the subscription. What should you use?',
   '[{"id":"a","text":"An Azure RBAC role assigned at the resource group scope","correct":true,"explanation":"RBAC grants only the needed permissions at the smallest useful scope."},{"id":"b","text":"Azure Policy","correct":false,"explanation":"Policy enforces rules on resources, it does not grant user permissions."},{"id":"c","text":"A resource lock","correct":false,"explanation":"Locks protect resources from changes, they do not assign user access."},{"id":"d","text":"The Owner role at subscription scope","correct":false,"explanation":"That gives far too much access and breaks least privilege."}]'::jsonb,
   2, false)
on conflict (id) do nothing;